// =============================================================================
// CONFIGURATION - EDIT ALL VALUES HERE!
// =============================================================================

const CONFIG = {
    // === IP ADDRESSES ===
    // Replace with your actual IP addresses
    EMHASS_IP: "emhass-ip",      // e.g., "192.168.1.100"
    EMHASS_PORT: 5000,

    // === TIBBER API ===
    // Get your token from https://developer.tibber.com/
    TIBBER_TOKEN: "<YOUR_TIBBER_TOKEN>",

    // === ELECTRICITY PRICES ===
    // Feed-in tariff in €/kWh
    FEED_IN_TARIFF: 0.0711,

    // === TIMEZONE ===
    // +01:00 for CET, +02:00 for CEST
    TIMEZONE: "+01:00",

    // === OPTIMIZATION ===
    // Planning horizon in 15-min steps
    DAYAHEAD_HORIZON: 96,  // 24h
    MPC_HORIZON: 48,       // 12h

    // === HYSTERESIS ===
    // Prevents flickering at small values
    HYSTERESIS_WATTS: 50
};

// Store in global context for other nodes
global.set('EMHASS_CONFIG', CONFIG);

// Build URLs
CONFIG.EMHASS_URL = `http://${CONFIG.EMHASS_IP}:${CONFIG.EMHASS_PORT}`;
CONFIG.EMHASS_DAYAHEAD = `${CONFIG.EMHASS_URL}/action/dayahead-optim`;
CONFIG.EMHASS_MPC = `${CONFIG.EMHASS_URL}/action/naive-mpc-optim`;
CONFIG.EMHASS_PUBLISH = `${CONFIG.EMHASS_URL}/action/publish-data`;

node.status({ fill: 'green', shape: 'dot', text: 'Config loaded' });

return null;

