// =============================================================================
// PAYLOAD BUILDER
// Collects PV forecast and SOC for EMHASS
// =============================================================================

const CONFIG = global.get('EMHASS_CONFIG');
if (!CONFIG) {
    node.error('Config not loaded! Please deploy first.');
    return null;
}

const isDayAhead = msg.trigger === 'dayahead';

const today = new Date();
const tomorrow = new Date(today);
tomorrow.setDate(tomorrow.getDate() + 1);

const todayStr = today.toISOString().split('T')[0];
const tomorrowStr = tomorrow.toISOString().split('T')[0];
const tz = CONFIG.TIMEZONE;

// PV Forecast from flow context (from Solcast MQTT)
let pv_forecast = {};

// Today
for (let h = 0; h < 24; h++) {
    const key = `solcast_td_w_${h}`;
    const value = flow.get(key) || 0;
    const timestamp = `${todayStr}T${h.toString().padStart(2,'0')}:00:00${tz}`;
    pv_forecast[timestamp] = parseFloat(value) || 0;
}

// Tomorrow (IMPORTANT for night optimization!)
for (let h = 0; h < 24; h++) {
    const key = `solcast_tm_w_${h}`;
    const value = flow.get(key) || 0;
    const timestamp = `${tomorrowStr}T${h.toString().padStart(2,'0')}:00:00${tz}`;
    pv_forecast[timestamp] = parseFloat(value) || 0;
}

// Battery SOC from Loxone
let soc_percent = flow.get('battery_soc') || 50;
if (soc_percent <= 0 || isNaN(soc_percent)) soc_percent = 50;
const soc_decimal = soc_percent / 100;

// Store for Tibber node
flow.set('emhass_pv_forecast', pv_forecast);
flow.set('emhass_soc', soc_decimal);
flow.set('emhass_type', isDayAhead ? 'dayahead' : 'mpc');

const type = isDayAhead ? 'Day-Ahead' : 'MPC';
node.status({
    fill: 'blue',
    shape: 'dot',
    text: `${type}: PV=${Object.keys(pv_forecast).length}h, SOC=${soc_percent}%`
});

return msg;

// =============================================================================
// TIBBER API - Fetch electricity prices
// =============================================================================

const CONFIG = global.get('EMHASS_CONFIG');

msg.method = 'POST';
msg.url = 'https://api.tibber.com/v1-beta/gql';
msg.headers = {
    'Authorization': `Bearer ${CONFIG.TIBBER_TOKEN}`,
    'Content-Type': 'application/json'
};

// GraphQL query for quarter-hourly prices
msg.payload = JSON.stringify({
    query: `{
        viewer {
            homes {
                currentSubscription {
                    priceInfo (resolution: QUARTER_HOURLY) {
                        today { total startsAt }
                        tomorrow { total startsAt }
                    }
                }
            }
        }
    }`
});

return msg;

// =============================================================================
// PARSE TIBBER RESPONSE + CALL EMHASS
// =============================================================================

const CONFIG = global.get('EMHASS_CONFIG');
const isDayAhead = flow.get('emhass_type') === 'dayahead';

let load_prices = {};
let prod_prices = {};

try {
    const data = msg.payload.data.viewer.homes[0].currentSubscription.priceInfo;

    if (data.today) {
        data.today.forEach(p => {
            load_prices[p.startsAt] = p.total;
            prod_prices[p.startsAt] = CONFIG.FEED_IN_TARIFF;
        });
    }

    if (data.tomorrow && data.tomorrow.length > 0) {
        data.tomorrow.forEach(p => {
            load_prices[p.startsAt] = p.total;
            prod_prices[p.startsAt] = CONFIG.FEED_IN_TARIFF;
        });
    }
} catch (e) {
    node.error('Tibber Error: ' + e.message);
    node.status({ fill: 'red', shape: 'ring', text: 'Tibber Error' });
    return null;
}

const pv_forecast = flow.get('emhass_pv_forecast') || {};
const soc = flow.get('emhass_soc') || 0.5;

const payload = {
    pv_power_forecast: pv_forecast,
    load_cost_forecast: load_prices,
    prod_price_forecast: prod_prices,
    prediction_horizon: isDayAhead ? CONFIG.DAYAHEAD_HORIZON : CONFIG.MPC_HORIZON,
    soc_init: Math.round(soc * 100) / 100,
    soc_final: 0.0
};

const type = isDayAhead ? 'Day-Ahead' : 'MPC';
node.warn(`${type}: PV=${Object.keys(pv_forecast).length}, Prices=${Object.keys(load_prices).length}`);

msg.url = isDayAhead ? CONFIG.EMHASS_DAYAHEAD : CONFIG.EMHASS_MPC;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = payload;

node.status({ fill: 'blue', shape: 'dot', text: `Sending ${type}...` });

return msg;

const type = flow.get('emhass_type') === 'dayahead' ? 'Day-Ahead' : 'MPC';

if (msg.statusCode === 200 || msg.statusCode === 201) {
    node.status({ fill: 'green', shape: 'dot', text: `${type} OK!` });
    node.warn(`${type} optimization successful!`);
    return [msg, { payload: {} }];
} else {
    node.status({ fill: 'red', shape: 'ring', text: `Error ${msg.statusCode}` });
    node.error(`${type} Error: ${msg.statusCode}`);
    return [null, null];
}

const CONFIG = global.get('EMHASS_CONFIG');
msg.url = CONFIG.EMHASS_PUBLISH;
msg.method = 'POST';
msg.payload = {};
return msg;

// =============================================================================
// EMHASS CSV PARSER v3
// 
// PRINCIPLE: EMHASS has already decided!
// We only translate to Sungrow commands.
//
// LOGIC:
// - P_batt < 0 + P_grid_pos > 0 → charge (grid charging is profitable!)
// - P_batt < 0 + P_grid_pos = 0 → discharge (PV surplus only)
// - P_batt > 0 → discharge (battery discharge)
// - else → hold (hold battery)
// =============================================================================

const CONFIG = global.get('EMHASS_CONFIG') || { HYSTERESIS_WATTS: 50 };
const HYSTERESIS = CONFIG.HYSTERESIS_WATTS;

const csv = msg.payload;
const lines = csv.trim().split('\n');

if (lines.length < 2) {
    node.error('CSV empty or malformed');
    return null;
}

// Parse header
const headers = lines[0].split(',');
const getIdx = (name) => headers.indexOf(name);

const idx = {
    timestamp: getIdx('timestamp'),
    p_batt: getIdx('P_batt'),
    soc: getIdx('SOC_opt'),
    p_grid_pos: getIdx('P_grid_pos'),
    p_pv: getIdx('P_PV'),
    p_load: getIdx('P_Load'),
    price: getIdx('unit_load_cost')
};

if (idx.p_batt === -1 || idx.soc === -1) {
    node.error('P_batt or SOC_opt not found!');
    return null;
}

// Parse all rows
const rows = [];
for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(',');
    if (cols.length < 5) continue;
    rows.push({
        timestamp: cols[idx.timestamp],
        p_batt: parseFloat(cols[idx.p_batt]) || 0,
        soc: parseFloat(cols[idx.soc]) || 0,
        p_grid_pos: parseFloat(cols[idx.p_grid_pos]) || 0,
        p_pv: parseFloat(cols[idx.p_pv]) || 0,
        p_load: parseFloat(cols[idx.p_load]) || 0,
        price: parseFloat(cols[idx.price]) || 0.25
    });
}

if (rows.length === 0) return null;

const current = rows[0];

// === DECISION LOGIC ===
let mode = 'hold';
let power = 0;
let reason = '';
let action = '';

if (current.p_batt < -HYSTERESIS) {
    // EMHASS wants to CHARGE
    power = Math.abs(current.p_batt);

    if (current.p_grid_pos > HYSTERESIS) {
        // Grid import planned → EMHASS says: IT'S PROFITABLE!
        mode = 'charge';
        reason = `EMHASS: Grid charge @ ${(current.price * 100).toFixed(1)}¢`;
        action = `Forced Charge ${Math.round(power)}W`;
    } else {
        // PV only → Self-Consumption
        mode = 'discharge';
        power = 0;
        reason = `PV surplus: ${Math.round(current.p_pv)}W`;
        action = 'Self-Consumption';
    }
} else if (current.p_batt > HYSTERESIS) {
    // EMHASS wants to DISCHARGE
    mode = 'discharge';
    power = 0;
    reason = `Battery → House: ${Math.round(current.p_batt)}W`;
    action = 'Self-Consumption';
} else {
    // EMHASS wants to HOLD
    mode = 'hold';
    power = 0;
    reason = `Hold SOC @ ${Math.round(current.soc * 100)}%`;
    action = 'Max Discharge = 10W';
}

// === FIND NEXT CHANGE ===
const getModeForRow = (row) => {
    if (row.p_batt < -HYSTERESIS) {
        return row.p_grid_pos > HYSTERESIS ? 'charge' : 'discharge';
    } else if (row.p_batt > HYSTERESIS) {
        return 'discharge';
    }
    return 'hold';
};

let next_change = 'No change planned';
let next_detail = '';

for (let i = 1; i < Math.min(rows.length, 48); i++) {
    const row = rows[i];
    const row_mode = getModeForRow(row);

    if (row_mode !== mode) {
        const mins = i * 15;
        const h = Math.floor(mins / 60);
        const m = mins % 60;
        const time_str = h > 0 ? `${h}h ${m}min` : `${m}min`;

        let time_display = row.timestamp;
        try {
            const d = new Date(row.timestamp);
            time_display = d.toLocaleTimeString('de-DE', {
                hour: '2-digit', minute: '2-digit'
            });
        } catch(e) {}

        next_change = `${row_mode.toUpperCase()} at ${time_display} (${time_str})`;

        if (row_mode === 'charge') {
            next_detail = `Grid charge @ ${(row.price * 100).toFixed(1)}¢`;
        } else if (row_mode === 'hold') {
            next_detail = `Hold SOC @ ${Math.round(row.soc * 100)}%`;
        } else {
            next_detail = 'Use battery';
        }
        break;
    }
}

// === OUTPUT ===
const result = {
    battery: {
        mode: mode,
        power: Math.round(power),
        power_signed: Math.round(current.p_batt),
        soc_target: Math.round(current.soc * 100)
    },
    status: {
        reason: reason,
        action: action,
        next_change: next_change,
        next_detail: next_detail
    },
    current: {
        timestamp: current.timestamp,
        price_cents: Math.round(current.price * 100),
        pv: Math.round(current.p_pv),
        load: Math.round(current.p_load),
        grid_import: Math.round(current.p_grid_pos),
        soc: Math.round(current.soc * 100)
    }
};

const colors = { charge: 'blue', discharge: 'green', hold: 'yellow' };
node.status({ fill: colors[mode], shape: 'dot', text: `${mode.toUpperCase()} | ${reason}` });

node.warn(`Mode: ${mode} | ${reason}`);

msg.payload = result;
return msg;

const d = msg.payload;

const messages = [
    // Control
    { topic: 'emhass/battery/mode', payload: d.battery.mode },
    { topic: 'emhass/battery/power', payload: d.battery.power },
    { topic: 'emhass/battery/soc_target', payload: d.battery.soc_target },
    { topic: 'emhass/battery/power_signed', payload: d.battery.power_signed },

    // Status
    { topic: 'emhass/status/reason', payload: d.status.reason },
    { topic: 'emhass/status/action', payload: d.status.action },
    { topic: 'emhass/status/next_change', payload: d.status.next_change },
    { topic: 'emhass/status/next_detail', payload: d.status.next_detail },

    // Current
    { topic: 'emhass/current/price_cents', payload: d.current.price_cents },
    { topic: 'emhass/current/pv', payload: d.current.pv },
    { topic: 'emhass/current/load', payload: d.current.load },
    { topic: 'emhass/current/soc', payload: d.current.soc }
];

node.status({ fill: 'green', shape: 'dot', text: `${d.battery.mode} | ${messages.length} topics` });

return [messages, msg];

// Topic: solcast/sum/hourly_td_w_12 → solcast_td_w_12
const topic = msg.topic;
const value = parseFloat(msg.payload) || 0;

const match = topic.match(/hourly_(t[dm]_w_\d+)$/);
if (match) {
    const key = 'solcast_' + match[1];
    flow.set(key, value);
}

return null;

let soc = parseFloat(msg.payload) || 0;
if (soc <= 0 || soc > 100 || isNaN(soc)) soc = 50;

flow.set('battery_soc', soc);
node.status({ fill: 'green', shape: 'dot', text: `SOC: ${soc}%` });

return null;
